<h2>Estimate property flip profit</h2><p class="lead">Model sale proceeds, total project cost, profit, ROI and break-even sale price for a property flip.</p><div class="notice">Add contingency to rehab/holding costs if appropriate. Taxes, financing structure and transaction fees vary by jurisdiction and deal.</div><div class="form-grid"><div class="field"><label for="buy">Purchase price</label><input id="buy" type="number" value="3000000" min="0" step="any"></div><div class="field"><label for="rehab">Renovation / rehab</label><input id="rehab" type="number" value="500000" min="0" step="any"></div><div class="field"><label for="hold">Holding + financing costs</label><input id="hold" type="number" value="200000" min="0" step="any"></div><div class="field"><label for="buyclose">Purchase closing costs</label><input id="buyclose" type="number" value="120000" min="0" step="any"></div><div class="field"><label for="sale">Expected sale price</label><input id="sale" type="number" value="4300000" min="0" step="any"></div><div class="field"><label for="sellpct">Selling costs (% of sale)</label><input id="sellpct" type="number" value="5" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Estimated profit</span><strong id="profit">—</strong></div><div class="metric"><span>ROI on project cost</span><strong id="roi">—</strong></div><div class="metric"><span>Total project cost</span><strong id="cost">—</strong></div><div class="metric"><span>Break-even sale price</span><strong id="breakeven">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('profit').textContent='—';$('roi').textContent='—';$('cost').textContent='—';$('breakeven').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const b=num('buy'),r=num('rehab'),h=num('hold'),bc=num('buyclose'),s=num('sale'),sp=num('sellpct');if(!(b>=0&&r>=0&&h>=0&&bc>=0&&s>=0&&sp>=0&&sp<100))throw 0;const base=b+r+h+bc,sell=s*sp/100,cost=base+sell,profit=s-cost,roi=base>0?profit/base*100:NaN,be=base/(1-sp/100);$('profit').textContent=fmt(profit,2);$('roi').textContent=Number.isFinite(roi)?fmt(roi,2)+'%':'—';$('cost').textContent=fmt(cost,2);$('breakeven').textContent=fmt(be,2);$('note').textContent='This is a project estimate before income/capital-gains tax and unexpected costs. Selling cost is modelled as a percentage of sale price.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
